# bar chart: tourists visiting a district (in lakh)
_YR=["2021","2022","2023","2024","2025"];_T=[12,18,15,24,30]
def _bar():
    s='<line x1="40" y1="170" x2="330" y2="170" stroke="currentColor"/><line x1="40" y1="20" x2="40" y2="170" stroke="currentColor"/>'
    for v in (10,20,30):
        y=170-v*5;s+='<line x1="36" y1="%d" x2="330" y2="%d" stroke="currentColor" stroke-opacity="0.2"/><text x="32" y="%d" text-anchor="end">%d</text>'%(y,y,y+4,v)
    for i,(yr,v) in enumerate(zip(_YR,_T)):
        x=58+i*55;h=v*5
        s+='<rect x="%d" y="%d" width="34" height="%d" fill="currentColor" fill-opacity="0.55"/><text x="%d" y="%d" text-anchor="middle" font-weight="700">%d</text><text x="%d" y="186" text-anchor="middle">%s</text>'%(x,170-h,h,x+17,165-h,v,x+17,yr)
    return '<svg viewBox="0 0 340 195" width="340" height="195" role="img" aria-label="bar chart"><g font-family="sans-serif" font-size="12" fill="currentColor">'+s+'</g></svg>'
BAR=_bar()
